"""[data/monsters_db.py] 라즈베리 파이 4 백엔드 - 전 몬스터 10종 & 보스 발록 스폰 및 레벨 비례 스탯 강화 DB"""
from typing import Any

def scale_monster_by_level(m: dict[str, Any]) -> dict[str, Any]:
    out = dict(m)
    lv = int(out.get("lv", 1))
    if lv <= 2:
        return out
    lv_factor = 1.0 + ((lv - 1) ** 1.28) * 0.16
    scaled_hp = int(round(out["maxHp"] * lv_factor))
    scaled_atk = int(round(out["atk"] * (1.0 + (lv - 1) * 0.14)))
    scaled_spd = int(round(out["spd"] * (1.0 + min(0.35, (lv - 1) * 0.025))))
    out["hp"] = scaled_hp
    out["maxHp"] = scaled_hp
    out["atk"] = scaled_atk
    out["spd"] = scaled_spd
    return out


